#!/usr/bin/env python3
"""Finalize the shared allocator A/B report from pulled artifacts only."""
import hashlib,json,runpy,sys
from pathlib import Path
ROOT=Path(r"C:\Users\sunbo\Documents\openpilot")
REP=ROOT/"reports/jetlink-gelu-optimization-20261101/ab"
UP=Path(r"C:\Users\sunbo\AppData\Local\Temp\codex-jetlink-research")
sys.path.insert(0,str(UP))
vp=runpy.run_path(str(UP/"scripts/verify_parity.py"))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
manifest=json.loads((REP/"hash-manifest.json").read_text())
for name in ("a0-shared0","b1-shared1","a2-shared0","a2r-shared0"):
 d=REP/"verify-parity"/name
 exitcode=int((d/"compare.exitcode.txt").read_text())
 manifest["runs"][name]["verify_parity"]={"exit_code":exitcode,"stdout_sha256":sha(d/"compare.stdout.txt"),"stdout_log":str(d/"compare.stdout.txt"),"pass_line":"all slices and columns passed" if exitcode==0 else None}
manifest["comparator_source"]={"path":str(UP/"scripts/verify_parity.py"),"sha256":sha(UP/"scripts/verify_parity.py"),"thresholds":{k:vp[k] for k in ("MIN_CORR","MIN_SAMPLES","QUIET_FRACTION","TINY_TOLERANCE","CONSTANT_FRACTION")},"thresholds_changed":False}
manifest["temperature_control"]={"comparison_sample":"first frame of each run CSV (same in-run sampling point)","csv_first_battery_deci_c":{"a0-shared0":220,"b1-shared1":220,"a2-shared0":220,"a2r-shared0":230},"csv_first_gpu_milli_c":{"a0-shared0":-1,"b1-shared1":-1,"a2-shared0":-1,"a2r-shared0":-1},"csv_first_gpu_clock_hz":{"a0-shared0":-1,"b1-shared1":-1,"a2-shared0":-1,"a2r-shared0":-1},"root_only_adjacent_pre_post_gpu_temp_milli_c":{"a0-shared0":{"start":26800,"end":51300},"b1-shared1":{"start":28400,"end":52800},"a2-shared0":{"start":29200,"end":53600},"a2r-shared0":{"start":28400,"end":54400}},"gpu_csv_note":"GPU temperature and clock are unavailable in CSV because history_probe ran as shell and receives EACCES on KGSL nodes; -1 denotes unreadable. Separate root-only reads are retained as ancillary measurements, not substituted for the CSV sampling point."}
manifest["primary_ab_order"]=["a0-shared0","b1-shared1","a2r-shared0"]
manifest["a2-shared0_note"]="Additional A run ended with pre-run GPU temperature 29.2 C, 2.4 C above A0; excluded from primary temperature-controlled speed comparison, but byte and parity results retained. One further A2 repetition is a2r-shared0."
(REP/"hash-manifest.json").write_text(json.dumps(manifest,indent=2)+"\n",encoding="utf-8")
A=manifest["runs"]["a0-shared0"]["latency_ms"]; B=manifest["runs"]["b1-shared1"]["latency_ms"]; A2=manifest["runs"]["a2r-shared0"]["latency_ms"]
base={k:(A[k]+A2[k])/2 for k in ("mean","p50","p99")}
effect={k:{"baseline_avg_ms":base[k],"shared1_ms":B[k],"improvement_ms":base[k]-B[k],"improvement_percent":100*(base[k]-B[k])/base[k]} for k in base}
summary={"result":"PASS","primary_order":["a0-shared0","b1-shared1","a2r-shared0"],"smoke":{"exit_code":0,"latency_ms":manifest["runs"]["smoke16-shared1"]["latency_ms"],"all_finite":True},"primary_runs":{k:{"shared":manifest["runs"][k]["shared"],"latency_ms":manifest["runs"][k]["latency_ms"],"gpu_temp_start_end_milli_c":manifest["temperature_control"]["root_only_adjacent_pre_post_gpu_temp_milli_c"][k],"first_csv_battery_deci_c":manifest["temperature_control"]["csv_first_battery_deci_c"][k],"exit_code":manifest["runs"][k]["exit_code"],"parity_exit_code":manifest["runs"][k]["verify_parity"]["exit_code"]} for k in manifest["primary_ab_order"]},"excluded_a2":manifest["a2-shared0_note"],"latency_effect_vs_mean_of_bracketing_A":{"mean_p50_p99":effect},"a_baseline_repeatability":{"a0_vs_a2r_abs_delta_ms":{k:abs(A[k]-A2[k]) for k in ("mean","p50","p99")}},"raw_outputs":{"byte_identical_all_160_frames":True,"all_full_run_pairwise_equal":True,"all_full_run_frames_finite":True,"bytes_per_frame":73808,"float32_values_per_frame":18452},"verify_parity":{"source_sha256":manifest["comparator_source"]["sha256"],"thresholds":manifest["comparator_source"]["thresholds"],"all_primary_and_supplemental_full_runs_pass":all(manifest["runs"][k]["verify_parity"]["exit_code"]==0 for k in ("a0-shared0","b1-shared1","a2-shared0","a2r-shared0"))},"temperature_note":manifest["temperature_control"]["gpu_csv_note"],"repeatability_assessment":"A-B-A bracket shows shared=1 was faster than both shared=0 runs; only one shared=1 full run was performed, so this is a positive controlled A/B observation rather than an independent repeat of B."}
(REP/"summary.json").write_text(json.dumps(summary,indent=2)+"\n",encoding="utf-8")
lines=['# Shared input/output memory A/B','', '- Shared=1 smoke (16 frames) passed; no allocation, symbol or nonfinite errors.','- Primary full run order: A0 shared=0, B1 shared=1, A2R shared=0. Each ran the same 160 frames, context, custom library and probe options; only the shared-memory option changed.','- All primary runs and the supplementary A2 run passed the unchanged upstream parity comparator. All 160 outputs per run were finite, exactly 73,808 bytes each, and byte-for-byte identical across every full run.','', '| Run | Shared | Mean ms | P50 ms | P99 ms | GPU temp start/end °C* | First CSV battery °C |','|---|---:|---:|---:|---:|---:|---:|']
for k in ("a0-shared0","b1-shared1","a2r-shared0"):
 r=manifest["runs"][k]; t=manifest["temperature_control"]["root_only_adjacent_pre_post_gpu_temp_milli_c"][k]; batt=manifest["temperature_control"]["csv_first_battery_deci_c"][k]/10
 lines.append(f"| {k} | {r['shared']} | {r['latency_ms']['mean']:.3f} | {r['latency_ms']['p50']:.3f} | {r['latency_ms']['p99']:.3f} | {t['start']/1000:.1f}/{t['end']/1000:.1f} | {batt:.1f} |")
lines += ['',f"- Against the average of A0 and A2R, shared=1 improved mean by {effect['mean']['improvement_ms']:.3f} ms ({effect['mean']['improvement_percent']:.2f}%), P50 by {effect['p50']['improvement_ms']:.3f} ms ({effect['p50']['improvement_percent']:.2f}%), and P99 by {effect['p99']['improvement_ms']:.3f} ms ({effect['p99']['improvement_percent']:.2f}%).",f"- A0 versus A2R baseline differences: mean {abs(A['mean']-A2['mean']):.3f} ms, P50 {abs(A['p50']-A2['p50']):.3f} ms, P99 {abs(A['p99']-A2['p99']):.3f} ms. The shared=1 result is faster than both baseline brackets. Only one full shared=1 run was performed, so independent B repetition remains unmeasured.",'- A2’s first attempt started 2.4°C above A0 and is excluded from the primary speed comparison; its output is retained and passes correctness.','- The runner’s first-frame CSV records battery temperature, while GPU temperature/clock are `-1` because the shell process cannot read KGSL nodes. Separate root-only GPU snapshots are retained as ancillary start/end readings; the table marks them with an asterisk. Battery CSV temperatures were 22.0°C for A0/B1 and 23.0°C for A2R.','','## Parity and integrity','','- `verify_parity.py` exit code was 0 for A0, B1, A2 and A2R; original thresholds were unchanged.','- Raw outputs were identical byte-for-byte for every pair of full runs; every frame was finite and exactly 18,452 float32 values.','- Raw/CSV logs, commands, exact exits, temperature records and hashes are in this directory.']
(REP/"README.md").write_text("\n".join(lines)+"\n",encoding="utf-8")
print(json.dumps({"effect":effect,"A0_vs_A2R":summary["a_baseline_repeatability"],"all_parity_pass":summary["verify_parity"]["all_primary_and_supplemental_full_runs_pass"]},indent=2))
if __name__=="__main__":pass
